validator:
extends Node

func _ready():
	run_validation()

func run_validation():
	var qm = _get_qm()
	qm.wipe_player_data()
	var quest_res = load("res://quests/shoot_em_up_quest.tres")
	qm.add_quest("Shoot Em Up", quest_res)
	var projectile_scene = load("res://scenes/projectile.tscn")
	var projectile = projectile_scene.instantiate()
	add_child(projectile)
	var issues = []
	projectile.position.y = -80
	projectile._physics_process(0.016)
	if not projectile.is_queued_for_deletion():
		issues.append("Projectile should free itself when leaving the play area")
	var enemy = Area2D.new()
	enemy.add_to_group("enemy")
	add_child(enemy)
	var quest = qm.get_player_quest("Shoot Em Up")
	var before = quest.quest_steps[quest.first_step].collected
	projectile = projectile_scene.instantiate()
	add_child(projectile)
	if projectile.has_method("_on_area_entered"):
		projectile._on_area_entered(enemy)
		var after = qm.get_player_quest("Shoot Em Up").quest_steps[quest.first_step].collected
		if after != before + 1:
			issues.append("Colliding with enemies must increment the kill step")
		if not projectile.is_queued_for_deletion():
			issues.append("Projectile should remove itself after damaging an enemy")
	else:
		issues.append("Projectile must react to enemies inside _on_area_entered")

	# Check UI elements exist for visual feedback
	var main_scene = load("res://scenes/main.tscn")
	var main = main_scene.instantiate()
	var ui = main.get_node_or_null("UI")
	if not ui:
		issues.append("Main scene must have a UI CanvasLayer for displaying quest progress")
	else:
		var quest_label = ui.get_node_or_null("QuestProgress")
		if not quest_label:
			issues.append("UI must have a QuestProgress Label node for displaying progress")
		elif not quest_label is Label:
			issues.append("QuestProgress must be a Label")
	main.free()

	qm.wipe_player_data()
	if issues.is_empty():
		print("VALIDATION_PASSED: Projectile updates quest steps correctly and UI is present for visual feedback")
	else:
		print("VALIDATION_FAILED: %s" % "; ".join(issues))
	get_tree().quit()

func _get_qm():
	return get_tree().root.get_node("QuestManager")

extends Node

func _ready():
	var player_scene: PackedScene = load("res://scenes/player.tscn")
	if player_scene == null:
		return _fail("Player scene not found at res://scenes/player.tscn")

	var player_instance = player_scene.instantiate()
	add_child(player_instance)

	if not player_instance is CharacterBody2D:
		return _fail("Player root must be CharacterBody2D")
	if player_instance.name != "Player":
		return _fail("Player root node must be named 'Player'")

	var animated_sprite: AnimatedSprite2D = player_instance.get_node_or_null("AnimatedSprite2D")
	if animated_sprite == null:
		return _fail("AnimatedSprite2D child missing on Player")

	var frames: SpriteFrames = animated_sprite.sprite_frames
	if frames == null:
		return _fail("Player AnimatedSprite2D has no SpriteFrames resource")

	var required_anims = ["default", "left", "right", "explode"]
	for anim_name in required_anims:
		if not frames.has_animation(anim_name):
			return _fail("AnimatedSprite2D missing '%s' animation" % anim_name)

	if animated_sprite.autoplay != "default":
		return _fail("AnimatedSprite2D autoplay must be 'default'")

	if not frames.get_animation_loop("default"):
		return _fail("'default' animation must loop")
	if not frames.get_animation_loop("left"):
		return _fail("'left' animation must loop")
	if not frames.get_animation_loop("right"):
		return _fail("'right' animation must loop")
	if frames.get_animation_loop("explode"):
		return _fail("'explode' animation must not loop")

	if frames.get_frame_count("default") != 1:
		return _fail("'default' animation must have exactly one frame")
	if not _texture_matches(frames.get_frame_texture("default", 0), "sprites-Sheet.png", Rect2(16, 0, 16, 16)):
		return _fail("'default' animation must use jet neutral frame at (16,0,16,16)")
	if not _texture_matches(frames.get_frame_texture("left", 0), "sprites-Sheet.png", Rect2(32, 0, 16, 16)):
		return _fail("'left' animation must use jet frame at (32,0,16,16)")
	if not _texture_matches(frames.get_frame_texture("right", 0), "sprites-Sheet.png", Rect2(48, 0, 16, 16)):
		return _fail("'right' animation must use jet frame at (48,0,16,16)")

	if frames.get_frame_count("explode") < 4:
		return _fail("'explode' animation must contain multiple frames from the smoke sheet")
	if not _texture_matches(frames.get_frame_texture("explode", 0), "Free Smoke Fx  Pixel 04.png", Rect2(0, 128, 64, 64)):
		return _fail("'explode' first frame must come from smoke sheet region (0,128,64,64)")
	if not _texture_matches(frames.get_frame_texture("explode", frames.get_frame_count("explode") - 1), "Free Smoke Fx  Pixel 04.png", Rect2(384, 128, 64, 64)):
		return _fail("'explode' animation should include later smoke frames (expect region 384,128,64,64)")

	var collision: CollisionShape2D = player_instance.get_node_or_null("CollisionShape2D")
	if collision == null:
		return _fail("CollisionShape2D child missing on Player")
	if not collision.shape is RectangleShape2D:
		return _fail("Player collider must be RectangleShape2D")
	if collision.shape.size != Vector2(16, 16):
		return _fail("Player collider must be 16×16")

	print("VALIDATION_PASSED: Player scene structure matches tutorial")
	get_tree().quit(0)

func _texture_matches(texture: Texture2D, path_suffix: String, region: Rect2) -> bool:
	if texture is AtlasTexture:
		var atlas := texture as AtlasTexture
		return atlas.atlas != null \
			and atlas.atlas.resource_path.ends_with(path_suffix) \
			and atlas.region == region
	return false

func _fail(message: String):
	print("VALIDATION_FAILED: %s" % message)
	get_tree().quit(1)

extends Node

var validation_done := false
var flash_count := 0
var max_flashes := 10

func _ready():
	run_validation()
	# Start repeatedly spawning muzzle flashes for visual feedback
	if validation_done:
		spawn_muzzle_flash()

func fail(msg: String) -> void:
	print("VALIDATION_FAILED: %s" % msg)
	get_tree().quit(1)

func succeed(msg: String) -> void:
	print("VALIDATION_PASSED: %s" % msg)
	validation_done = true

func spawn_muzzle_flash() -> void:
	var effect_scene = load("res://scenes/effects/muzzle_flash_effect.tscn")
	var effect = effect_scene.instantiate()
	get_node("Main").add_child(effect)
	effect.global_position = Vector3(0, 0, 0)

	flash_count += 1
	if flash_count < max_flashes:
		# Wait 0.8 seconds before spawning next flash
		await get_tree().create_timer(0.8).timeout
		spawn_muzzle_flash()
	else:
		# Wait 1 second before quitting
		await get_tree().create_timer(1.0).timeout
		get_tree().quit()

func run_validation() -> void:
	var effect = get_node_or_null("Main/MuzzleFlashEffect")
	if not effect:
		fail("Main must instance the MuzzleFlashEffect scene")
		return

	var script = effect.get_script()
	if script == null or String(script.resource_path).find("generic_effect_handler.gd") == -1:
		fail("MuzzleFlashEffect must use generic_effect_handler.gd")
		return

	if effect.get("optional_light_path") != NodePath("MuzzleFlash"):
		fail("Optional light export must point to the MuzzleFlash OmniLight")
		return

	if abs(effect.get("light_duration") - 0.2) > 0.01:
		fail("Light duration must be 0.2 seconds")
		return

	var omni = effect.get_node_or_null("MuzzleFlash")
	if not (omni is OmniLight3D):
		fail("MuzzleFlash node must be an OmniLight3D")
		return

	var smoke = effect.get_node_or_null("SmokeParticles")
	if not (smoke is GPUParticles3D):
		fail("SmokeParticles GPUParticles3D is missing")
		return

	if not smoke.process_material:
		fail("SmokeParticles needs a process material for lifetime control")
		return

	if smoke.process_material is ParticleProcessMaterial:
		if smoke.process_material.gravity != Vector3.ZERO:
			fail("SmokeParticles gravity must be (0, 0, 0) to prevent falling")
			return

	if smoke.draw_pass_1 == null:
		fail("SmokeParticles must render with a mesh draw pass")
		return

	var smoke_mesh = smoke.draw_pass_1
	if smoke_mesh.material == null:
		fail("SmokeParticles mesh must have a material assigned")
		return

	if not (smoke_mesh.material is StandardMaterial3D):
		fail("SmokeParticles mesh must use a StandardMaterial3D")
		return

	if smoke_mesh.material.billboard_mode != BaseMaterial3D.BILLBOARD_PARTICLES:
		fail("SmokeParticles material must use Billboard Mode (Particles) to look volumetric")
		return
	if not (smoke_mesh.material.albedo_texture is GradientTexture2D):
		fail("SmokeParticles material must use a GradientTexture2D (procedural radial puff)")
		return

	if smoke_mesh.material.albedo_texture.fill != GradientTexture2D.FILL_RADIAL:
		fail("SmokeParticles gradient texture must be Radial to look like a round puff")
		return

	for name in ["MuzzleFireLeft", "MuzzleFireRight"]:
		var fire_node = effect.get_node_or_null(name)
		if not (fire_node is GPUParticles3D):
			fail("%s must be a GPUParticles3D" % name)
			return
		if fire_node.process_material == null:
			fail("%s needs a process material" % name)
			return
		var mat = fire_node.material_override
		if not (mat is ShaderMaterial) or mat.shader == null:
			fail("%s must use the muzzle flash shader material" % name)
			return
		var shader_path = String(mat.shader.resource_path)
		if shader_path.find("muzzle_flash.gdshader") == -1:
			fail("%s must reference assets/shaders/muzzle_flash.gdshader" % name)
			return
		if fire_node.draw_pass_1 == null:
			fail("%s must define a draw pass mesh" % name)
			return

	succeed("Muzzle flash effect configured with light and particles")

extends Node

const REQUIRED_EXPORTS := [
    "camera_shake_noise",
    "camera_shake_noise_panning_speed",
    "camera_shake_max_power",
    "camera_shake_blend_speed",
    "camera_shake_return_strength",
    "camera_shake_noise_strength",
    "camera_shake_falling_bias",
    "camera_shake_falling_strength_falloff",
    "camera_shake_falling_max_strength",
    "camera_shake_jumping_strength",
]

const EXPECTED_DEFAULTS := {
    "camera_shake_noise_panning_speed": 30.0,
    "camera_shake_max_power": 0.15,
    "camera_shake_blend_speed": 7.0,
    "camera_shake_return_strength": 5.0,
    "camera_shake_noise_strength": 0.2,
    "camera_shake_falling_bias": 1.0,
    "camera_shake_falling_strength_falloff": 2.0,
    "camera_shake_falling_max_strength": 1.0,
    "camera_shake_jumping_strength": 0.2,
}

var _failed := false

func _ready() -> void:
    run_validation()

func fail(reason: String) -> void:
    if _failed:
        return
    _failed = true
    print("VALIDATION_FAILED: %s" % reason)
    get_tree().quit(1)

func run_validation() -> void:
    var scene: PackedScene = load("res://scenes/player_body.tscn")
    var player_body = scene.instantiate()
    add_child(player_body)
    await get_tree().process_frame

    _check_camera_hierarchy(player_body)
    if _failed:
        return
    _check_exports(player_body)
    if _failed:
        return
    _check_defaults(player_body)
    if _failed:
        return
    _check_noise_assignment(player_body)
    if _failed:
        return
    _check_impulse_behaviour(player_body)
    if _failed:
        return
    _check_landing_impulse(player_body)
    if _failed:
        return
    print("VALIDATION_PASSED: Camera shake rig matches tutorial expectations")
    get_tree().quit()

func _check_camera_hierarchy(player_body) -> void:
    var camera_node = player_body.get_node_or_null("CameraNode")
    if camera_node == null:
        fail("CameraNode missing under PlayerBody")
        return
    var camera_actual = camera_node.get_node_or_null("CameraActual")
    if camera_actual == null:
        fail("CameraActual missing under CameraNode")
        return
    var camera_3d = camera_actual.get_node_or_null("Camera3D")
    if camera_3d == null:
        fail("Camera3D child missing under CameraActual")
        return

func _check_exports(player_body) -> void:
    var property_map := {}
    for info in player_body.get_property_list():
        property_map[info.name] = info
    for property_name in REQUIRED_EXPORTS:
        if not property_map.has(property_name):
            fail("Export '%s' missing on PlayerBody" % property_name)
            return
        var usage: int = int(property_map[property_name].usage)
        if (usage & PROPERTY_USAGE_EDITOR) == 0:
            fail("Export '%s' must be exposed to the editor" % property_name)
            return

func _check_defaults(player_body) -> void:
    for property_name in EXPECTED_DEFAULTS.keys():
        var expected_value: float = EXPECTED_DEFAULTS[property_name]
        var actual_value = player_body.get(property_name)
        if not is_equal_approx(float(actual_value), expected_value):
            fail("Default for %s should be %s" % [property_name, expected_value])
            return

func _check_noise_assignment(player_body) -> void:
    var noise = player_body.get("camera_shake_noise")
    if noise == null or not (noise is FastNoiseLite):
        fail("camera_shake_noise must be a FastNoiseLite resource")
        return

func _check_impulse_behaviour(player_body) -> void:
    var camera_actual = player_body.camera_actual
    if camera_actual == null:
        fail("camera_actual export must be assigned")
        return
    var initial_time := float(player_body.get("time_since_started"))
    player_body.impulse_camera(Vector3.UP, player_body.camera_shake_max_power * 5.0)
    if player_body.camera_shake_position.length() > player_body.camera_shake_max_power + 0.001:
        fail("impulse_camera must clamp camera_shake_position to camera_shake_max_power")
        return
    player_body._physics_process(0.1)
    if camera_actual.position.length() <= 0.0:
        fail("CameraActual should move away from origin after impulse")
        return
    for i in range(60):
        player_body._physics_process(0.1)
    if camera_actual.position.length() > 0.01:
        fail("CameraActual should blend back to origin")
        return
    if float(player_body.get("time_since_started")) <= initial_time:
        fail("time_since_started must increase each frame")
        return
    var previous_position: Vector3 = player_body.camera_shake_position
    player_body.impulse_camera_with_recoil(Vector3.BACK, 0.05)
    if player_body.camera_shake_position.y <= previous_position.y:
        fail("impulse_camera_with_recoil should add upward kick")
        return

func _check_landing_impulse(player_body) -> void:
    var camera_actual = player_body.camera_actual
    player_body.camera_shake_position = Vector3.ZERO
    if camera_actual:
        camera_actual.position = Vector3.ZERO
    player_body.apply_landing_impulse(-3.0)
    player_body._physics_process(0.05)
    if camera_actual and camera_actual.position.y >= 0.0:
        fail("apply_landing_impulse should add downward offset when landing")
        return

extends Node

var _failed := false

func _ready() -> void:
    run_validation()

func fail(reason: String) -> void:
    if _failed:
        return
    _failed = true
    print("VALIDATION_FAILED: %s" % reason)
    get_tree().quit(1)

func run_validation() -> void:
    var scene: PackedScene = load("res://scenes/main.tscn")
    var root = scene.instantiate()
    add_child(root)
    await get_tree().process_frame

    var player = root.get_node_or_null("PlayerBody")
    var weapon = root.get_node_or_null("WeaponEffects")
    if player == null or weapon == null:
        fail("PlayerBody or WeaponEffects missing from Main scene")
        return

    if not weapon.has_signal("on_shot_camera_impulse"):
        fail("WeaponEffects must declare on_shot_camera_impulse signal")
        return

    if not weapon.has_method("fire_weapon"):
        fail("WeaponEffects must expose fire_weapon()")
        return

    if not player.has_method("apply_weapon_impulse"):
        fail("PlayerBody needs apply_weapon_impulse() handler")
        return

    var connection := Callable(player, "apply_weapon_impulse")
    if not weapon.is_connected("on_shot_camera_impulse", connection):
        fail("Connect WeaponEffects.on_shot_camera_impulse to PlayerBody.apply_weapon_impulse")
        return

    var power_property := weapon.get_property_list().filter(func(info): return info.name == "camera_shake_power")
    if power_property.is_empty():
        fail("camera_shake_power export missing on WeaponEffects")
        return

    if not is_equal_approx(float(weapon.get("camera_shake_power")), 0.3):
        fail("camera_shake_power default must be 0.3")
        return

    var ray_cast = weapon.get_node_or_null("BarrelEnd/BarrelRayCast")
    if ray_cast == null:
        fail("BarrelRayCast missing under WeaponEffects")
        return

    player.camera_shake_position = Vector3.ZERO
    weapon.fire_weapon()
    await get_tree().process_frame

    if player.camera_shake_position.length() <= 0.0:
        fail("apply_weapon_impulse should forward weapon recoil to PlayerBody")
        return

    if player.camera_shake_position.z >= 0.0:
        fail("Impulse direction should push camera backwards along -Z")
        return

    if _failed:
        return
    print("VALIDATION_PASSED: Weapon recoil signal wired into PlayerBody")
    get_tree().quit()

extends Node

var flashlight_point_script: Script
var required_points := {
	"PillarPoint": {
		"priority": 1,
		"position": Vector3(8.36166, 1.81915, -12.0301)
	},
	"GatePoint": {
		"priority": 0,
		"position": Vector3(-16.6577, 2.41884, -39.9426)
	},
	"EnemyPoint": {
		"priority": 2,
		"position": Vector3(23.0185, 2.63927, -86.6948)
	}
}

func _ready():
	flashlight_point_script = load("res://scripts/flashlight_point.gd")
	if flashlight_point_script == null:
		_fail("scripts/flashlight_point.gd is missing")
		return
	run_validation()

func run_validation():
	var main := get_node_or_null("Main")
	if main == null:
		_fail("Main scene not instanced")
		return

	var camera := main.get_node_or_null("Camera3D")
	if camera == null or not (camera is Camera3D):
		_fail("Camera3D node missing or wrong type")
		return

	for point_name in required_points.keys():
		var node := main.get_node_or_null(point_name)
		if node == null:
			_fail(point_name + " node missing")
			return
		if not node.is_in_group("FlashlightPoints"):
			_fail(point_name + " is not in FlashlightPoints group")
			return
		if not (node is Marker3D):
			_fail(point_name + " is not a Marker3D")
			return
		if node.get_script() != flashlight_point_script:
			_fail(point_name + " is not using flashlight_point.gd")
			return

		if not node.has_method("reset_target_state"):
			_fail(point_name + " script missing reset_target_state() method")
			return

		var priority_value = node.get("priority")
		if typeof(priority_value) != TYPE_INT:
			_fail(point_name + " priority property missing")
			return
		var expected_priority: int = required_points[point_name]["priority"]
		if priority_value != expected_priority:
			_fail(point_name + " priority incorrect")
			return

		var targeted_value = node.get("has_been_targeted")
		if typeof(targeted_value) != TYPE_BOOL:
			_fail(point_name + " missing has_been_targeted flag")
			return
		if targeted_value:
			_fail(point_name + " should start un-targeted")
			return

		var expected_pos: Vector3 = required_points[point_name]["position"]
		if node.global_position.distance_to(expected_pos) > 0.05:
			_fail(point_name + " position mismatch: " + str(node.global_position))
			return

	print("VALIDATION_PASSED: Flashlight priority points configured")
	get_tree().quit()

func _fail(message: String) -> void:
	print("VALIDATION_FAILED: " + message)
	get_tree().quit(1)

extends Node

const REQUIRED_RESOURCE := "res://assets/clouds/tutorial_clouds_settings.tres"
const REQUIRED_CAMERA_FAR := 400000.0
const REQUIRED_COVERAGE := 0.874
const REQUIRED_ATMOSPHERIC_DENSITY := 0.617977
const REQUIRED_AMBIENT_TINT := Color(0.131626, 0.201524, 0.241773, 1)
const REQUIRED_ATMOSPHERE_COLOR := Color(0.696127, 0.832325, 0.989334, 1)

func _ready():
	run_validation()

func run_validation():
	var main = get_node_or_null("Main")
	if main == null:
		_fail("Main scene missing")
		return

	var camera = main.get_node_or_null("Camera3D")
	if camera == null or not (camera is Camera3D):
		_fail("Camera3D node missing")
		return
	if camera.far < REQUIRED_CAMERA_FAR - 0.5:
		_fail("Camera far plane must be set to 400000")
		return

	var world_env = main.get_node_or_null("WorldEnvironment")
	if world_env == null or not (world_env is WorldEnvironment):
		_fail("WorldEnvironment node missing")
		return
	if world_env.compositor == null:
		_fail("WorldEnvironment.compositor not assigned")
		return
	if world_env.compositor.compositor_effects.size() != 1:
		_fail("WorldEnvironment must have exactly one compositor effect")
		return

	var driver = main.get_node_or_null("SunshineCloudsDriver")
	if driver == null:
		_fail("SunshineCloudsDriver node missing")
		return
	var driver_script = driver.get_script()
	if driver_script == null or not driver_script.resource_path.ends_with("SunshineCloudsDriver.gd"):
		_fail("SunshineCloudsDriver must use addons/SunshineClouds2/SunshineCloudsDriver.gd")
		return

	if not driver.update_continuously:
		_fail("SunshineCloudsDriver must update continuously")
		return

	var clouds_resource = driver.get("clouds_resource")
	if clouds_resource == null:
		_fail("clouds_resource not assigned")
		return
	if clouds_resource.resource_path != REQUIRED_RESOURCE:
		_fail("Driver must reference " + REQUIRED_RESOURCE)
		return

	if world_env.compositor.compositor_effects[0] != clouds_resource:
		_fail("WorldEnvironment compositor must reuse the same clouds resource")
		return

	if driver.ambience_sample_environment != world_env.environment:
		_fail("Driver ambience_sample_environment must point to the WorldEnvironment resource")
		return

	if not _array_has_reference(driver.get("tracked_directional_lights"), "../DirectionalLight3D", driver):
		_fail("Directional light is not registered on the driver")
		return

	var shadow_steps = driver.get("tracked_directional_light_shadow_steps")
	if shadow_steps.size() != 1 or shadow_steps[0] != 32:
		_fail("Directional light shadow steps must contain a single entry set to 32")
		return

	if not _array_has_reference(driver.get("tracked_point_lights"), "../OmniLight3D", driver):
		_fail("Omni light is not wired to the driver")
		return

	var omni = main.get_node_or_null("OmniLight3D")
	if omni == null or not (omni is OmniLight3D):
		_fail("OmniLight3D missing from scene")
		return
	if omni.omni_range < 20000.0:
		_fail("OmniLight3D range must be at least 20000 to match the tutorial example")
		return

	if not _is_equal_approx(clouds_resource.clouds_coverage, REQUIRED_COVERAGE, 0.001):
		_fail("Cloud coverage must be set to " + str(REQUIRED_COVERAGE))
		return
	if not _is_equal_approx(clouds_resource.atmospheric_density, REQUIRED_ATMOSPHERIC_DENSITY, 0.001):
		_fail("Atmospheric density must be lowered to ~0.618")
		return

	if clouds_resource.cloud_ambient_color != Color(1, 1, 1, 1):
		_fail("Cloud ambient color must be pure white")
		return
	if not _is_color_close(clouds_resource.cloud_ambient_tint, REQUIRED_AMBIENT_TINT, 0.01):
		_fail("Cloud ambient tint must match the darker blue tint from the resource guide")
		return
	if not _is_color_close(clouds_resource.atmosphere_color, REQUIRED_ATMOSPHERE_COLOR, 0.01):
		_fail("Atmosphere color must be the cooler blue tone from the tutorial settings")
		return

	if clouds_resource.mask_width_km < 400.0:
		_fail("Mask width should remain large to cover the play space")
		return

	print("VALIDATION_PASSED: Sunshine Clouds driver and lighting configured")
	get_tree().quit()

func _array_has_reference(arr: Array, path: String, driver: Node) -> bool:
	var expected_path = NodePath(path)
	for entry in arr:
		match typeof(entry):
			TYPE_NODE_PATH:
				if NodePath(entry).get_concatenated_names() == expected_path.get_concatenated_names():
					return true
			TYPE_OBJECT:
				if entry is Node:
					var node = driver.get_node_or_null(expected_path)
					if node != null and entry == node:
						return true
	return false

func _is_equal_approx(a: float, b: float, tolerance: float) -> bool:
	return abs(a - b) <= tolerance

func _is_color_close(a: Color, b: Color, tolerance: float) -> bool:
	return abs(a.r - b.r) <= tolerance and abs(a.g - b.g) <= tolerance and abs(a.b - b.b) <= tolerance

func _fail(message: String) -> void:
	print("VALIDATION_FAILED: " + message)
	get_tree().quit(1)

