const REQUIRED_IDLE = ["idle0", "idle1", "idle2", "idle3", "idle4", "idle5", "idle6", "idle7"]
const REQUIRED_RUN = ["run0", "run1", "run2", "run3", "run4", "run5", "run6", "run7"]

func _ready() -> void:
	await get_tree().process_frame
	run_validation()

func run_validation() -> void:
	var main = get_node_or_null("Main")
	if main == null:
		return _fail("VALIDATION_FAILED: Main scene is missing")

	var player = main.get_node_or_null("Player")
	if player == null:
		return _fail("VALIDATION_FAILED: Add the Player scene to Main")
	if not (player is CharacterBody2D):
		return _fail("VALIDATION_FAILED: Player must be a CharacterBody2D root")
	if player.motion_mode != CharacterBody2D.MOTION_MODE_FLOATING:
		return _fail("VALIDATION_FAILED: Set Player.motion_mode to Floating for 8-direction movement")

	var animated_sprite = player.get_node_or_null("AnimatedSprite2D")
	if animated_sprite == null:
		return _fail("VALIDATION_FAILED: Player needs an AnimatedSprite2D child")
	if animated_sprite.sprite_frames == null:
		return _fail("VALIDATION_FAILED: AnimatedSprite2D must use the Crusader SpriteFrames resource")
	var frames: SpriteFrames = animated_sprite.sprite_frames
	for anim_name in REQUIRED_IDLE + REQUIRED_RUN:
		if not frames.has_animation(anim_name):
			return _fail("VALIDATION_FAILED: Missing %s animation" % anim_name)

	# test frame usage
	for anim_name in REQUIRED_IDLE:
		if frames.get_frame_count(anim_name) != 16:
			return _fail("VALIDATION_FAILED: Idle animations need multiple frames from the sprites")
		if frames.get_frame_texture(anim_name, 0) is not AtlasTexture:
			return _fail("VALIDATION_FAILED: Animation texture should be AtlasTexture")
		if not frames.get_frame_texture(anim_name, 0).atlas.resource_path.contains("crusader_idle"):
			return _fail("VALIDATION_FAILED: Idle animations used wrong frames")

	if not frames.get_frame_texture("idle4", 1).region == Rect2(299, 1440, 299, 240):
		return _fail("VALIDATION_FAILED: Idle animations atlas was sliced incorrectly")
	if not frames.get_frame_texture("idle7", 2).region == Rect2(598, 720, 299, 240):
		return _fail("VALIDATION_FAILED: Idle animations atlas was sliced incorrectly")


	for anim_name in REQUIRED_RUN:
		if frames.get_frame_count(anim_name) != 17:
			return _fail("VALIDATION_FAILED: Run animations must include the directional frames")
		if frames.get_frame_texture(anim_name, 0) is not AtlasTexture:
			return _fail("VALIDATION_FAILED: Animation texture should be AtlasTexture")
		if not frames.get_frame_texture(anim_name, 0).atlas.resource_path.contains("crusader_walk"):
			return _fail("VALIDATION_FAILED: Run animations used wrong frames")

	if not frames.get_frame_texture("run4", 1).region == Rect2(299, 1440, 299, 240):
		return _fail("VALIDATION_FAILED: Run animations atlas was sliced incorrectly")
	if not frames.get_frame_texture("run7", 2).region == Rect2(598, 720, 299, 240):
		return _fail("VALIDATION_FAILED: Run animations atlas was sliced incorrectly")

	if animated_sprite.animation != "idle0":
		return _fail("VALIDATION_FAILED: Default animation should start at idle0")
	if not is_equal_approx(animated_sprite.speed_scale, 2.0):
		return _fail("VALIDATION_FAILED: AnimatedSprite2D.speed_scale must be 2.0")

	# test frame offset correctness



	var collider = player.get_node_or_null("CollisionShape2D")
	if collider == null:
		return _fail("VALIDATION_FAILED: Player requires a CollisionShape2D child")
	if not (collider.shape is RectangleShape2D):
		return _fail("VALIDATION_FAILED: CollisionShape2D must use a RectangleShape2D")
	var rect := collider.shape as RectangleShape2D
	if rect.size != Vector2(66, 24):
		return _fail("VALIDATION_FAILED: Crusader rectangle size should be 66x24")
	if collider.position.distance_to(Vector2(7, 44)) > 0.1:
		return _fail("VALIDATION_FAILED: Collider offset must be positioned at (7, 44)")

	print("VALIDATION_PASSED: Crusader AnimatedSprite2D and collider are configured")
	get_tree().quit(0)

func _fail(message: String) -> void:
	print(message)
	get_tree().quit(1)

extends Node

const REQUIRED_ANIMS = ["up", "down", "left", "right"]

func _ready() -> void:
	await get_tree().process_frame
	run_validation()

func run_validation() -> void:
	var main = get_node_or_null("Main")
	if not main:
		return _fail("VALIDATION_FAILED: Main scene is missing")

	var player = main.get_node_or_null("Player")
	if not player:
		return _fail("VALIDATION_FAILED: Player instance not found under Main")
	if not (player is Area2D):
		return _fail("VALIDATION_FAILED: Player must be an Area2D root")

	var sprite = player.get_node_or_null("Sprite2d")
	if not sprite:
		return _fail("VALIDATION_FAILED: Add a Sprite2d child to Player")
	if sprite.texture == null:
		return _fail("VALIDATION_FAILED: Sprite2d must use the sokoban_character texture")
	if sprite.texture.resource_path != "res://assets/sokoban_character.png":
		return _fail("VALIDATION_FAILED: Sprite2d texture must be res://assets/sokoban_character.png")
	if sprite.hframes != 6 or sprite.vframes != 4:
		return _fail("VALIDATION_FAILED: Sprite2d hframes/vframes must be 6x4 as in the tutorial")

	var collider = player.get_node_or_null("CollisionShape2d")
	if not collider:
		return _fail("VALIDATION_FAILED: Player needs a CollisionShape2d child")
	if not (collider.shape is RectangleShape2D):
		return _fail("VALIDATION_FAILED: CollisionShape2d must use a RectangleShape2D")
	var rect = collider.shape as RectangleShape2D
	if rect.size != Vector2(32, 32):
		return _fail("VALIDATION_FAILED: RectangleShape2D size must be 32x32 pixels")

	var ray = player.get_node_or_null("RayCast2d")
	if not ray:
		return _fail("VALIDATION_FAILED: Add a RayCast2d child to Player")
	if not ray.collide_with_areas:
		return _fail("VALIDATION_FAILED: RayCast2d must enable collide_with_areas")

	var anim_player = player.get_node_or_null("AnimationPlayer")
	if not anim_player:
		return _fail("VALIDATION_FAILED: Player needs an AnimationPlayer for walk cycles")
	for anim_name in REQUIRED_ANIMS:
		if not anim_player.has_animation(anim_name):
			return _fail("VALIDATION_FAILED: AnimationPlayer must include a '%s' animation" % anim_name)
		var anim = anim_player.get_animation(anim_name)
		if anim.get_track_count() == 0:
			return _fail("VALIDATION_FAILED: Animation '%s' must animate Sprite2d.frame" % anim_name)
		var path : NodePath = anim.track_get_path(0)
		if not path.get_name(path.get_name_count() - 1).contains("Sprite2d"):
			return _fail("VALIDATION_FAILED: Animation '%s' must key Sprite2d.frame" % anim_name)
		if not path.get_subname(path.get_subname_count() - 1).contains("frame"):
			return _fail("VALIDATION_FAILED: Animation '%s' must key Sprite2d.frame" % anim_name)
		if anim.track_get_key_count(0) < 4:
			return _fail("VALIDATION_FAILED: Animation '%s' needs keyframes for movement" % anim_name)

	print("VALIDATION_PASSED: Player node hierarchy matches the grid movement tutorial")
	get_tree().quit(0)

func _fail(message: String) -> void:
	print(message)
	get_tree().quit(1)

extends Node

func _ready():
	run_validation()


func fail(message: String) -> void:
	print("VALIDATION_FAILED: %s" % message)
	get_tree().quit(1)


func run_validation() -> void:
	var demo := get_node("AudioDemo")
	if not (demo is MarginContainer):
		return fail("Root AudioDemo must be a MarginContainer")
	if not demo.get_script() or not demo.get_script().resource_path.ends_with("scripts/audio_demo.gd"):
		return fail("AudioDemo must use res://scripts/audio_demo.gd")
	if demo.sound_dir != "res://assets":
		return fail("sound_dir should default to res://assets")

	for margin in ["margin_left", "margin_top", "margin_right", "margin_bottom"]:
		if demo.get_theme_constant(margin) != 20:
			return fail("Margins should be 20 on all sides")

	var center := demo.get_node_or_null("CenterContainer")
	if not center or not (center is CenterContainer):
		return fail("CenterContainer not found")
	var grid := center.get_node_or_null("GridContainer")
	if not grid or not (grid is GridContainer):
		return fail("GridContainer not found")
	if grid.columns != 2:
		return fail("GridContainer should use two columns")
	if grid.get_theme_constant("h_separation") != 10 or grid.get_theme_constant("v_separation") != 10:
		return fail("GridContainer spacing should be 10")

	var canvas := demo.get_node_or_null("CanvasLayer")
	if not canvas:
		return fail("CanvasLayer missing")
	var bar := canvas.get_node_or_null("HBoxContainer")
	if not bar or not (bar is HBoxContainer):
		return fail("HBoxContainer missing")

	var labels := {
		"Label": "Available Streams:",
		"Label2": "0",
		"Label4": "Queue:",
		"Label3": "0",
	}
	for name in labels.keys():
		var label := bar.get_node_or_null(name)
		if not label or not (label is Label):
			return fail("%s label missing" % name)
		if label.text != labels[name]:
			return fail("%s text incorrect" % name)
		var font = label.get_theme_font("font")
		if not font or not font.resource_path.ends_with("assets/Poppins-Medium.ttf"):
			return fail("%s must use Poppins-Medium font" % name)
		if label.get_theme_font_size("font_size") != 24:
			return fail("%s font size should be 24" % name)

	if not get_node_or_null("/root/AudioManager"):
		return fail("AudioManager autoload must be present for the UI to work")

	var dir := DirAccess.open(demo.sound_dir)
	if not dir:
		return fail("sound_dir cannot be opened")
	var audio_files: Array = []
	dir.list_dir_begin()
	var fname := dir.get_next()
	while fname != "":
		if fname.get_extension() in ["wav", "ogg"]:
			audio_files.append(fname)
		fname = dir.get_next()
	dir.list_dir_end()
	audio_files.sort()

	var buttons := []
	for child in grid.get_children():
		if child is Button:
			buttons.append(child)
	if buttons.size() != audio_files.size():
		return fail("Button count (%s) must match audio files (%s)" % [buttons.size(), audio_files.size()])

	var button_names := []
	for b in buttons:
		button_names.append(b.text)
		if not b.is_connected("pressed", Callable(demo, "on_audio_button_pressed")):
			return fail("Buttons must connect pressed to on_audio_button_pressed")
	button_names.sort()
	if button_names != audio_files:
		return fail("Button labels must list all audio filenames from sound_dir")

	# Reset AudioManager state and verify stats update logic.
	var audio_manager := get_node("/root/AudioManager")
	audio_manager.queue.clear()
	audio_manager.available.clear()
	audio_manager.available.append_array(audio_manager.get_children())

	demo._process(0.0)
	if bar.get_node("Label2").text != str(audio_manager.available.size()):
		return fail("Available count label must reflect AudioManager.available size")
	if bar.get_node("Label3").text != str(audio_manager.queue.size()):
		return fail("Queue label must reflect AudioManager.queue size")

	var first_button: Button = buttons[0]
	first_button.emit_signal("pressed")
	if audio_manager.queue.size() == 0:
		return fail("Button press should enqueue audio path via AudioManager.play")

	audio_manager._process(0.0)
	demo._process(0.0)
	if audio_manager.available.size() != audio_manager.num_players - 1:
		return fail("AudioManager should be using exactly one player after processing queue")
	if bar.get_node("Label2").text != str(audio_manager.available.size()):
		return fail("Available label should update after playback starts")
	if bar.get_node("Label3").text != str(audio_manager.queue.size()):
		return fail("Queue label should update after playback")

	print("VALIDATION_PASSED: Audio demo UI lists sounds, wires buttons, and reflects AudioManager stats")
	get_tree().quit()

extends Node

const SHADER_PATH := "res://shaders/weapon_clip_and_fov_shader.gdshader"
const EXPECTED_FOV := 54.0

func _ready():
	await get_tree().process_frame
	run_validation()

func run_validation():
	var root := get_tree().current_scene
	if root == null:
		print("VALIDATION_FAILED: Current scene not found")
		get_tree().quit(1)
		return

	var shader_applier = _find_shader_applier(root)
	if shader_applier == null:
		print("VALIDATION_FAILED: Node with apply_clip_and_fov_shader_to_view_model not found")
		get_tree().quit(1)
		return

	var view_model_root = _find_view_model_root(shader_applier)
	if view_model_root == null:
		print("VALIDATION_FAILED: View model node with MeshInstance3D children not found")
		get_tree().quit(1)
		return

	var mesh_instance = _find_first_mesh_instance(view_model_root)
	if mesh_instance == null:
		print("VALIDATION_FAILED: No MeshInstance3D found under view model node")
		get_tree().quit(1)
		return

	var mesh = mesh_instance.mesh
	if mesh == null:
		print("VALIDATION_FAILED: MeshInstance3D has no mesh")
		get_tree().quit(1)
		return

	var base_mat = mesh.surface_get_material(0)
	if base_mat == null or not (base_mat is BaseMaterial3D):
		print("VALIDATION_FAILED: Base material is missing or not a BaseMaterial3D")
		get_tree().quit(1)
		return

	var expected_albedo: Color = base_mat.albedo_color
	var expected_metallic: float = base_mat.metallic
	var expected_roughness: float = base_mat.roughness

	shader_applier.apply_clip_and_fov_shader_to_view_model(view_model_root, EXPECTED_FOV)

	var surface_material = mesh.surface_get_material(0)
	if not surface_material or not (surface_material is ShaderMaterial):
		print("VALIDATION_FAILED: Surface material is not a ShaderMaterial")
		get_tree().quit(1)
		return

	var shader_mat := surface_material as ShaderMaterial
	if not shader_mat.shader:
		print("VALIDATION_FAILED: ShaderMaterial has no shader")
		get_tree().quit(1)
		return
	if shader_mat.shader.resource_path != SHADER_PATH:
		print("VALIDATION_FAILED: Shader path is incorrect")
		get_tree().quit(1)
		return

	var fov_value = float(shader_mat.get_shader_parameter("viewmodel_fov"))
	if abs(fov_value - EXPECTED_FOV) > 0.01:
		print("VALIDATION_FAILED: viewmodel_fov must be set to 54.0")
		get_tree().quit(1)
		return

	var albedo_value = shader_mat.get_shader_parameter("albedo")
	if not _color_close(albedo_value, expected_albedo, 0.01):
		print("VALIDATION_FAILED: Shader albedo parameter was not copied from base material")
		get_tree().quit(1)
		return

	var metallic_value = float(shader_mat.get_shader_parameter("metallic"))
	if abs(metallic_value - expected_metallic) > 0.01:
		print("VALIDATION_FAILED: Shader metallic parameter was not copied from base material")
		get_tree().quit(1)
		return

	var roughness_value = float(shader_mat.get_shader_parameter("roughness"))
	if abs(roughness_value - expected_roughness) > 0.01:
		print("VALIDATION_FAILED: Shader roughness parameter was not copied from base material")
		get_tree().quit(1)
		return

	print("VALIDATION_PASSED: View model shader applied and configured")
	get_tree().quit(1)

func _find_shader_applier(root: Node) -> Node:
	var nodes = root.find_children("*", "Node", true, false)
	for node in nodes:
		if node.has_method("apply_clip_and_fov_shader_to_view_model"):
			return node
	return null

func _find_view_model_root(root: Node) -> Node3D:
	var nodes = root.find_children("*", "Node3D", true, false)
	for node in nodes:
		var mesh_children = node.find_children("*", "MeshInstance3D", true, false)
		if mesh_children.size() > 0:
			return node as Node3D
	return null

func _find_first_mesh_instance(root: Node) -> MeshInstance3D:
	if root is MeshInstance3D:
		return root
	var nodes = root.find_children("*", "MeshInstance3D", true, false)
	return nodes[0] if nodes.size() > 0 else null

func _color_close(a: Color, b: Color, eps: float) -> bool:
	return abs(a.r - b.r) <= eps and abs(a.g - b.g) <= eps and abs(a.b - b.b) <= eps and abs(a.a - b.a) <= eps

extends Node

var _failed := false

func _ready():
	run_validation()

func run_validation():
	_validate_world_scene()
	if _failed:
		return
	_validate_world_script()
	if _failed:
		return
	_validate_tank_scene()
	if _failed:
		return
	_validate_tank_script()
	if _failed:
		return

	print("VALIDATION_PASSED: Task completed successfully")
	get_tree().quit(0)

func _validate_world_scene():
	var world_scene: PackedScene = load("res://scenes/world.tscn")
	if world_scene == null:
		fail("world.tscn not found or empty")
		return
	var world = world_scene.instantiate()
	if world == null:
		fail("world.tscn failed to instantiate")
		return
	var tile_map = world.get_node_or_null("TileMap")
	if tile_map == null or !(tile_map is TileMap):
		fail("World missing TileMap node")
		return
	var tile_set: TileSet = tile_map.tile_set
	if tile_set == null:
		fail("TileMap missing TileSet")
		return
	var found_tile_type := false
	for i in range(tile_set.get_custom_data_layers_count()):
		if tile_set.get_custom_data_layer_name(i) == "tile_type":
			found_tile_type = true
			if tile_set.get_custom_data_layer_type(i) != TYPE_INT:
				fail("tile_type custom data layer must be type int")
				return
	if !found_tile_type:
		fail("TileSet missing tile_type custom data layer")
		return

	var water_color = world.get("water_color")
	var dirt_color = world.get("dirt_color")
	var grass_color = world.get("grass_color")
	if water_color == null or !(water_color is GradientTexture1D):
		fail("World node missing water_color GradientTexture1D")
		return
	if dirt_color == null or !(dirt_color is GradientTexture1D):
		fail("World node missing dirt_color GradientTexture1D")
		return
	if grass_color == null or !(grass_color is GradientTexture1D):
		fail("World node missing grass_color GradientTexture1D")
		return

	world.queue_free()

func _validate_world_script():
	var world_script_text = FileAccess.get_file_as_string("res://scripts/world.gd")
	if world_script_text.is_empty():
		fail("world.gd not found or empty")
		return
	if world_script_text.find("enum TILE_TYPES") == -1:
		fail("World is missing TILE_TYPES enum")
		return
	if world_script_text.find("get_gradient_at") == -1:
		fail("World is missing get_gradient_at")
		return
	if world_script_text.find("tile_type") == -1:
		fail("get_gradient_at must read tile_type custom data")
		return
	if world_script_text.find("water_color") == -1 or world_script_text.find("dirt_color") == -1 or world_script_text.find("grass_color") == -1:
		fail("World must reference water_color, dirt_color, and grass_color")
		return

func _validate_tank_scene():
	var tank_scene: PackedScene = load("res://scenes/tank.tscn")
	if tank_scene == null:
		fail("tank.tscn not found or empty")
		return
	var tank = tank_scene.instantiate()
	if tank == null:
		fail("tank.tscn failed to instantiate")
		return
	var left = tank.get_node_or_null("LeftTrackParticles")
	if left == null or !(left is GPUParticles2D):
		fail("Tank scene missing LeftTrackParticles GPUParticles2D")
		return
	var right = tank.get_node_or_null("RightTrackParticles")
	if right == null or !(right is GPUParticles2D):
		fail("Tank scene missing RightTrackParticles GPUParticles2D")
		return

	_check_particles(left, -16.0, "LeftTrackParticles")
	_check_particles(right, 16.0, "RightTrackParticles")

	tank.queue_free()

func _check_particles(particles: GPUParticles2D, expected_dir_y: float, label: String):
	if particles.amount != 128:
		fail("%s.amount must be 128" % label)
		return
	if particles.z_index != -1:
		fail("%s.z_index must be -1" % label)
		return
	if particles.emitting != false:
		fail("%s.emitting must start disabled" % label)
		return

	var material = particles.process_material
	if material == null or !(material is ParticleProcessMaterial):
		fail("%s.process_material must be ParticleProcessMaterial" % label)
		return
	if material.emission_shape != ParticleProcessMaterial.EMISSION_SHAPE_BOX:
		fail("%s.process_material must use box emission" % label)
		return
	if !_approx(material.emission_box_extents.x, -16.0):
		fail("%s.emission_box_extents.x must be -16" % label)
		return
	if !_approx(material.direction.y, expected_dir_y):
		fail("%s.direction.y must be %s" % [label, str(expected_dir_y)])
		return
	if !_approx(material.spread, 25.0):
		fail("%s.spread must be 25" % label)
		return
	if material.gravity != Vector3.ZERO:
		fail("%s.gravity must be zero" % label)
		return
	if !_approx(material.initial_velocity_max, 4.0):
		fail("%s.initial_velocity_max must be 4" % label)
		return
	if !_approx(material.damping_max, 3.0):
		fail("%s.damping_max must be 3" % label)
		return
	if !_approx(material.scale_min, 0.25):
		fail("%s.scale_min must be 0.25" % label)
		return

func _validate_tank_script():
	var tank_script_text = FileAccess.get_file_as_string("res://scripts/tank.gd")
	if tank_script_text.is_empty():
		fail("tank.gd not found or empty")
		return
	if tank_script_text.find("World.get_gradient_at") == -1:
		fail("Tank is missing World.get_gradient_at call")
		return
	if tank_script_text.find("color_ramp") == -1:
		fail("Tank does not apply particle gradient to color_ramp")
		return
	if !_has_emitting_value(tank_script_text, true) or !_has_emitting_value(tank_script_text, false):
		fail("Tank must enable and disable particles while moving")
		return

func _has_emitting_value(text: String, value: bool) -> bool:
	var pattern = ""
	if value:
		pattern = "emitting\\s*=\\s*true|set_emitting\\s*\\(\\s*true\\s*\\)"
	else:
		pattern = "emitting\\s*=\\s*false|set_emitting\\s*\\(\\s*false\\s*\\)"
	var re = RegEx.new()
	var err = re.compile(pattern)
	if err != OK:
		return false
	return re.search(text) != null

func _approx(a: float, b: float) -> bool:
	return is_equal_approx(a, b)

func fail(reason: String):
	_failed = true
	print("VALIDATION_FAILED: %s" % reason)
	get_tree().quit(1)

